multi_queries.type_and_summary:
PREFIX hist: <http://www.example.org/korean-history#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?entity ?entityLabel ?type ?summary ?category ?year WHERE {
    ?entity rdfs:label ?entityLabel .
    FILTER (?entityLabel = "당쟁" || ?entityLabel = "1764 가솔 강제편입" || ?entityLabel = "1763 비변사 보고 및 균역법 기준 징세" || ?entityLabel = "1778년(정조 2) 가쇄 규정 축소" || ?entityLabel = "1761년(영조 37) 유생에 대한 칼 면제 특권 부여" || ?entityLabel = "증광문과 병과 급제" || ?entityLabel = "형조판서 임명" || ?entityLabel = "진사시 합격")
    OPTIONAL { ?entity rdf:type ?type }
    OPTIONAL { ?entity hist:hasSummary ?summary }
    OPTIONAL { ?entity hist:hasCategory ?category }
    OPTIONAL { ?entity hist:hasYear ?year }
} LIMIT 50

